#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string S;
    if (!(cin >> S)) return 0;

    int n = S.length();
    vector<int> suf_p(n + 1, 0);
    for (int i = n - 1; i >= 0; --i) {
        suf_p[i] = suf_p[i + 1] + (S[i] == 'P' ? 1 : 0);
    }

    // Pola siklus OSN:
    vector<string> patterns = {"OSN", "ONS", "SNO", "SON", "NOS", "NSO"};

    int max_len = -1;

    for (const string &pat : patterns) {
        vector<int> pref_match(n, 0);
        int matched = 0;
        for (int i = 0; i < n; ++i) {
            if (S[i] == pat[matched % 3]) {
                matched++;
            }
            pref_match[i] = matched;
        }

        for (int i = 0; i < n; ++i) {
            if (pref_match[i] >= 3 && suf_p[i + 1] >= 1) {
                max_len = max(max_len, pref_match[i] + suf_p[i + 1]);
            }
        }
    }

    cout << max_len << "\n";
    return 0;
}

#include <iostream>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long N, P, L;
    if (!(cin >> N >> P >> L)) return 0;

    // Binary search panjang sisi gudang S
    long long low = 1, high = 4e9;
    long long ans = high;

    while (low <= high) {
        long long mid = low + (high - low) / 2;
        __int128 cap = (__int128)(mid / P) * (mid / L);
        if (cap >= N) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }

    cout << ans << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

long long count_divisors(long long val) {
    long long cnt = 0;
    for (long long i = 1; i * i <= val; ++i) {
        if (val % i == 0) {
            cnt++;
            if (i * i != val) cnt++;
        }
    }
    return cnt;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long N;
    if (!(cin >> N)) return 0;

    // Cari faktor-faktor prima dari N
    vector<long long> primes;
    long long temp = N;
    for (long long d = 2; d * d <= temp; ++d) {
        if (temp % d == 0) {
            primes.push_back(d);
            while (temp % d == 0) temp /= d;
        }
    }
    if (temp > 1) primes.push_back(temp);

    // K adalah pembagi N. Untuk meminimalkan k dan memaksimalkan d(N * k),
    // kandidat optimal selalu berada pada faktor prima terkecil dari N
    long long best_k = primes[0];
    long long max_div = 0;

    for (long long p : primes) {
        long long d_count = count_divisors(N * p);
        if (d_count > max_div) {
            max_div = d_count;
            best_k = p;
        } else if (d_count == max_div && p < best_k) {
            best_k = p;
        }
    }

    cout << best_k << "\n";
    return 0;
}

