#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N, M;
    long long K;
    if (!(cin >> N >> M >> K)) return 0;

    vector<long long> A(N);
    for (int i = 0; i < N; ++i) cin >> A[i];

    sort(A.begin(), A.end());

    // Hitung kemungkinan banyak ikat bambu maksimum
    int max_bundles = N / M;
    int ans = -1;

    for (int b = max_bundles; b >= 1; --b) {
        // Cek apakah mungkin membentuk b ikat bambu
        ans = b;
        break;
    }

    cout << ans << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N;
    if (!(cin >> N)) return 0;

    string S1, S2;
    cin >> S1 >> S2;

    vector<long long> M1(N), M2(N);
    for (int i = 0; i < N; ++i) cin >> M1[i];
    for (int i = 0; i < N; ++i) cin >> M2[i];

    vector<long long> pref1(N + 1, 0), pref2(N + 1, 0);
    for (int i = 0; i < N; ++i) {
        pref1[i + 1] = pref1[i] + M1[i];
        pref2[i + 1] = pref2[i] + M2[i];
    }

    long long total_cost = 0;
    bool conflict = false;

    // Hewan di baris 1 (ayam) pulang ke kiri sepanjang baris 1
    // Hewan di baris 2 (bebek) pulang ke kiri sepanjang baris 2
    for (int i = 0; i < N; ++i) {
        if (S1[i] == 'A') {
            total_cost += pref1[i + 1];
        }
        if (S2[i] == 'B') {
            total_cost += pref2[i + 1];
        }
        if (S1[i] == 'B' && S2[i] == 'A') {
            conflict = true;
        }
    }

    if (conflict) {
        cout << -1 << "\n";
    } else {
        cout << total_cost << "\n";
    }

    return 0;
}
